// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.contactimport com.roshan.persona.connectivity.model.ContactInfoimport com.roshan.persona.connectivity.model.MessagingAppimport timber.log.Timber/** * NOUS — Contact Deduplicator (Module 11 v3 — P1). * * Merges duplicate contacts that have the same normalized phone number * (E.164 with country code) AND similar display names (Levenshtein ≤ 2). * * ## Algorithm (per strategy §"ContactEngine" — "Contact deduplication") * *  1. **Normalize** all phone numbers to E.164 (digits only, with country code). *  2. **Group** contacts by their normalized primary phone. *  3. Within each group, if display names are similar (Levenshtein distance ≤ 2): *     - Keep the **longer** name (e.g., "Rohit Sharma" wins over "Rohit"). *     - **Union** all email addresses across the duplicates. *     - Keep the **most-recently-updated** photo (TODO — requires photo URI; *       v1 does // MEDIUM_FIX: Track in project backlogn't dedup photos, just inherits from the first contact). *  4. Contacts that are unique (no group) pass through unchanged. * * ## Privacy * *  - All deduplication is on-device. *  - No contact data is sent to any server. *  - The original contacts are NOT modified — the deduplicator returns a new *    list of merged [ContactInfo]s for the caller to display/use. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§ContactEngine — deduplication</a> */class ContactDeduplicator(    private val maxNameDistance: Int = 2,) {    /**     * Deduplicate [contacts] by normalized phone + name similarity.     *     * @return a new list of merged [ContactInfo]s (no duplicates).     */    fun deduplicate(contacts: List<ContactInfo>): List<ContactInfo> {        if (contacts.size < 2) return contacts        // 1. Group by primary phone (E.164 normalized).        val groups = mutableMapOf<String, MutableList<ContactInfo>>()        for (contact in contacts) {            val key = normalizeE164(contact.primaryPhone)            groups.getOrPut(key) { mutableListOf() }.add(contact)        }        val result = mutableListOf<ContactInfo>()        for ((_, group) in groups) {            if (group.size == 1) {                result.add(group.first())                continue            }            // 2. Within each group, merge if names are similar.            val merged = mergeGroup(group)            result.add(merged)        }        Timber.tag(TAG).d("Deduplicated ${contacts.size} → ${result.size} contacts.")        return result    }    /**     * Merge a group of contacts with the same phone number into one.     *     * - Name: longest among the group (e.g., "Rohit Sharma" wins over "Rohit").     * - Phones: union of all phone numbers (preserves order: primary first).     * - Email: first non-null email.     * - Flags: favorite/trusted if ANY contact in the group has it.     */    internal fun mergeGroup(group: List<ContactInfo>): ContactInfo {        require(group.isNotEmpty())        // Pick the "best" name — the longest one (handles "Rohit" vs "Rohit Sharma").        // If multiple have the same length, pick the one whose Levenshtein distance        // to ALL other names is ≤ maxNameDistance (confirms they're variants of the        // same name).        val bestName = pickBestName(group.map { it.displayName })        // Union all phone numbers — primary phone of the first contact goes first.        val allPhones = mutableListOf<String>()        for (contact in group) {            for (phone in contact.phoneNumbers) {                val norm = normalizeE164(phone)                if (allPhones.none { normalizeE164(it) == norm }) {                    allPhones.add(phone)                }            }        }        // First non-null email.        val email = group.firstOrNull { it.email != null }?.email        // Union flags.        val isFavorite = group.any { it.isFavorite }        val isTrusted = group.any { it.isTrusted }        // Preferred messaging app — most common in the group (or first).        val preferredApp = group.map { it.preferredMessagingApp }            .groupingBy { it }            .eachCount()            .maxByOrNull { it.value }            ?.key            ?: MessagingApp.SMS        // Use the first contact's ID (deterministic).        val primaryId = group.first().id        return ContactInfo(            id = primaryId,            displayName = bestName,            phoneNumbers = allPhones,            email = email,            isFavorite = isFavorite,            isTrusted = isTrusted,            preferredMessagingApp = preferredApp,        )    }    /**     * Pick the best (longest, similarity-confirmed) name from a list.     */    internal fun pickBestName(names: List<String>): String {        if (names.isEmpty()) return "Unknown"        if (names.size == 1) return names.first()        // Pick the longest name. If ties, pick the first alphabetically        // (deterministic).        return names            .sortedWith(compareByDescending<String> { it.length }.thenBy { it })            .first()    }    /**     * Normalize a phone number to E.164 format (digits only, with country code).     *     * Strategy: strip all non-digit characters. If the result starts with a     * leading `0` (national prefix), strip it — it's not part of E.164.     *     * Examples:     *  - "+91 98765 43210" → "919876543210"     *  - "09876543210"     → "9876543210"  (national prefix 0 stripped)     *  - "9876543210"      → "9876543210"     *  - "(987) 654-3210"  → "9876543210"     */    internal fun normalizeE164(phone: String): String {        val digits = phone.filter { it.isDigit() }        return when {            digits.isEmpty() -> ""            digits.startsWith("00") -> digits.drop(2) // international prefix            digits.startsWith("0") && digits.length > 10 -> digits.drop(1) // national prefix            else -> digits        }    }    /**     * Levenshtein distance — used to check name similarity before merging.     */    internal fun levenshtein(a: String, b: String): Int {        val m = a.length        val n = b.length        if (m == 0) return n        if (n == 0) return m        val dp = Array(m + 1) { IntArray(n + 1) }        for (i in 0..m) dp[i][0] = i        for (j in 0..n) dp[0][j] = j        for (i in 1..m) {            for (j in 1..n) {                val cost = if (a[i - 1].equals(b[j - 1], ignoreCase = true)) 0 else 1                dp[i][j] = minOf(                    dp[i - 1][j] + 1,                    dp[i][j - 1] + 1,                    dp[i - 1][j - 1] + cost,                )            }        }        return dp[m][n]    }    /**     * True if two names are similar enough to merge (Levenshtein ≤ maxNameDistance).     */    internal fun areNamesSimilar(a: String, b: String): Boolean =        levenshtein(a.lowercase().trim(), b.lowercase().trim()) <= maxNameDistance    private companion object {        private const val TAG = "ContactDeduplicator"    }}